effect.shader:
float wave(vec2 p,float t){float a=sin(p.x*1.3+t)+sin(p.y*1.7-t*.8)+sin((p.x+p.y)*1.1+t*.6)+sin(length(p)*2.2-t);return a*.25;}void main(){vec2 uv=acScreenNorm,p=(uv-.5)*scale;float t=acTime*speed+evolution;float e=.03;float v=wave(p,t),gx=wave(p+vec2(e,0),t)-wave(p-vec2(e,0),t),gy=wave(p+vec2(0,e),t)-wave(p-vec2(0,e),t);float caustic=pow(clamp(1.0-length(vec2(gx,gy))/e*.12,0.0,1.0),sharpness);caustic*=mix(1.0,1.0-uv.y,depthFade)*intensity;vec4 src=texture2DCv(inputImg.texture,uv);vec3 light=lightColor.rgb*caustic;vec3 screen=1.0-(1.0-src.rgb)*(1.0-clamp(light,0.0,1.0));gl_FragColor=vec4(mix(src.rgb,screen,mixAmount),src.a+clamp(caustic,0.0,1.0)*mixAmount*(1.0-src.a));
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
